#!/usr/bin/env python3
"""Drop predicted CDS that sit inside a LONGER opposite-strand prediction.

Motivation (EXPERIMENTS.md 2026-09-20/22): raising the segmental decoder's
existence weight recovers real small genes, but the false positives it adds are
overwhelmingly *antisense* -- short ORFs called on the reverse complement of a
gene the decoder already found. On the psORF benchmark, 71.5% of the FP growth
from lead -> e100 was nested opposite-strand calls, while same-strand FP stayed
flat at 16-21 across every arm.

The rule is purely geometric -- no score column is needed (the decoder writes
'.' in GFF column 6) -- so this runs as post-processing on any prediction file:

    a call is dropped if >= `--containment` of ITS OWN length lies inside a
    single opposite-strand call that is strictly longer.

"Strictly longer" makes the relation antisymmetric, so a pair can never delete
each other. Containment is measured against the shorter call's length, which is
what makes the rule specific to embedded ORFs rather than ordinary gene overlap.
"""
from __future__ import annotations
import argparse
from pathlib import Path


def parse(path: Path):
    """Return (lines, records) where records index CDS rows in `lines`."""
    lines = path.read_text().splitlines()
    recs = []
    for i, line in enumerate(lines):
        if line.startswith("#"):
            continue
        f = line.split("\t")
        if len(f) < 8 or f[2] != "CDS":
            continue
        recs.append({"i": i, "seqid": f[0], "start": int(f[3]), "end": int(f[4]), "strand": f[6]})
    return lines, recs


def drop_indices(recs, containment: float) -> set[int]:
    by_seq: dict[str, list[dict]] = {}
    for r in recs:
        by_seq.setdefault(r["seqid"], []).append(r)
    dropped: set[int] = set()
    for calls in by_seq.values():
        # longest first, so the first qualifying container is found fast
        longer = sorted(calls, key=lambda c: -(c["end"] - c["start"]))
        for r in calls:
            L = r["end"] - r["start"] + 1
            need = containment * L
            for q in longer:
                if (q["end"] - q["start"] + 1) <= L:
                    break  # sorted: nothing after this is longer
                if q["strand"] == r["strand"]:
                    continue
                ov = min(r["end"], q["end"]) - max(r["start"], q["start"]) + 1
                if ov >= need:
                    dropped.add(r["i"])
                    break
    return dropped


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--input", type=Path, required=True)
    ap.add_argument("--output", type=Path, required=True)
    ap.add_argument("--containment", type=float, default=0.6,
                    help="fraction of the shorter call's length that must be covered (default 0.6)")
    ap.add_argument("--quiet", action="store_true")
    args = ap.parse_args()

    lines, recs = parse(args.input)
    dropped = drop_indices(recs, args.containment)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("\n".join(
        line for i, line in enumerate(lines) if i not in dropped
    ) + "\n")
    if not args.quiet:
        print(f"{args.input.name}: {len(recs)} CDS -> {len(recs) - len(dropped)} "
              f"({len(dropped)} dropped, containment>={args.containment})")


if __name__ == "__main__":
    main()
